17	package routingalgorithms
18	
19	import (
20		"context"
21		"errors"
22		"fmt"
23		"math"
24		"strconv"
25		"strings"
26		"sync"
27		"time"
28	
29		"github.com/vllm-project/aibrix/pkg/types"
30		v1 "k8s.io/api/core/v1"
31		"k8s.io/klog/v2"
32	)
33	
34	const (
35		RouterNotSet = ""
36	)
37	
38	var (
39		ErrInitTimeout           = errors.New("router initialization timeout")
40		ErrFallbackNotSupported  = errors.New("router not support fallback")
41		ErrFallbackNotRegistered = errors.New("fallback router not registered")
42		defaultRM                = NewRouterManager()
43	)
44	
45	// RouterItem represents a single routing algorithm and its weight coefficient for multi-router config.
46	type RouterItem struct {
47		Name        string
48		Coefficient int // Integer weight coefficient (0 to 1000000)
49	}
50	
51	// MultiRouterConfig holds the parsed routing algorithms and their weight coefficients.
52	type MultiRouterConfig struct {
53		Items []RouterItem
54	}
55	
56	// ParseMultiRouterConfig parses a multi-router string into a MultiRouterConfig.
57	// Format example: "prefix-cache:2,least-latency:1,least-request"
58	// - Weight coefficients must be integers in range [0, 1000000].
59	// - Default weight coefficient is 1 if omitted.
60	// - Weight coefficient 0 means the routing algorithm should be skipped.
61	func ParseMultiRouterConfig(routerStr string) (*MultiRouterConfig, error) {
62		if routerStr == "" {
63			return nil, errors.New("empty routing algorithm")
64		}
65	
66		parts := strings.Split(routerStr, ",")
67		if len(parts) == 0 {
68			return nil, errors.New("invalid routing algorithm format")
69		}
70	
71		var items []RouterItem
72	
73		for _, part := range parts {
74			part = strings.TrimSpace(part)
75			if part == "" {
76				return nil, errors.New("empty algorithm name")
77			}
78	
79			name := part
80			coefInt := 1 // Default weight coefficient is 1
81	
82			if strings.Contains(part, ":") {
83				subParts := strings.Split(part, ":")
84				if len(subParts) != 2 {
85					return nil, fmt.Errorf("invalid algorithm format: %s", part)
86				}
87				name = strings.TrimSpace(subParts[0])
88				if name == "" {
89					return nil, fmt.Errorf("empty algorithm name in: %s", part)
90				}
91	
92				coefStr := strings.TrimSpace(subParts[1])
93				parsedCoef, err := strconv.Atoi(coefStr)
94				if err != nil {
95					return nil, fmt.Errorf("invalid weight coefficient in: %s (must be an integer)", part)
96				}
97				if parsedCoef < 0 || parsedCoef > 1000000 {
98					return nil, fmt.Errorf("weight coefficient out of bounds [0, 1000000] in: %s", part)
99				}
100				coefInt = parsedCoef
101			}
102	
103			// If weight coefficient is 0, we skip this algorithm entirely
104			if coefInt > 0 {
105				items = append(items, RouterItem{Name: name, Coefficient: coefInt})
106			}
107		}
108	
109		if len(items) == 0 {
110			return nil, errors.New("no valid algorithms found (all weight coefficients were 0)")
111		}
112	
113		// Check for exclusive strategies (pd, slo*)
114		// If found, we ignore other strategies and return just the exclusive one
115		// If multiple exclusive strategies are found, the first one encountered wins
116		for _, item := range items {
117			if item.Name == "pd" || strings.HasPrefix(item.Name, "slo") {
118				klog.V(4).Infof("Exclusive routing strategy '%s' found in multi-strategy config. Other strategies will be ignored.", item.Name)
119				return &MultiRouterConfig{Items: []RouterItem{{Name: item.Name, Coefficient: 1}}}, nil
120			}
121		}
122	
123		return &MultiRouterConfig{Items: items}, nil
124	}
125	
126	// multiStrategyRouter coordinates multiple sub-routers and selects a pod via soft-scoring
127	type multiStrategyRouter struct {
128		config  *MultiRouterConfig
129		scorers map[string]types.PodScorer
130	}
131	
132	// newMultiStrategyRouter initializes a new multiStrategyRouter based on the parsed config
133	func newMultiStrategyRouter(config *MultiRouterConfig, rm *RouterManager, ctx *types.RoutingContext) (*multiStrategyRouter, error) {
134		scorers := make(map[string]types.PodScorer)
135	
136		for _, item := range config.Items {
137			rm.routerMu.RLock()
138			provider, ok := rm.routerFactory[types.RoutingAlgorithm(item.Name)]
139			rm.routerMu.RUnlock()
140	
141			if !ok {
142				return nil, fmt.Errorf("strategy %s not registered", item.Name)
143			}
144	
145			router, err := provider(ctx)
146			if err != nil {
147				return nil, fmt.Errorf("failed to initialize strategy %s: %v", item.Name, err)
148			}
149	
150			scorer, ok := router.(types.PodScorer)
151			if !ok {
152				return nil, fmt.Errorf("strategy %s does not implement types.PodScorer interface", item.Name)
153			}
154			scorers[item.Name] = scorer
155		}
156	
157		return &multiStrategyRouter{
158			config:  config,
159			scorers: scorers,
160		}, nil
161	}
162	
163	// Route executes the multi-strategy scoring pipeline and returns the best pod IP
164	func (m *multiStrategyRouter) Route(ctx *types.RoutingContext, readyPodList types.PodList) (string, error) {
165		pods := readyPodList.All()
166		if len(pods) == 0 {
167			return "", errors.New("empty pod list")
168		}
169	
170		if len(pods) == 1 {
171			ctx.SetTargetPod(pods[0])
172			m.setTargetPortIfNeeded(ctx, readyPodList, pods[0])
173			m.runPostRouteUpdates(ctx, readyPodList, pods[0])
174			return ctx.TargetAddress(), nil
175		}
176	
177		topPod, _, err := m.scoreAndRank(ctx, readyPodList)
178		if err != nil {
179			return "", err
180		}
181	
182		// Store target pod for updating cache if needed
183		ctx.SetTargetPod(topPod)
184		m.setTargetPortIfNeeded(ctx, readyPodList, topPod)
185		m.runPostRouteUpdates(ctx, readyPodList, topPod)
186	
187		return ctx.TargetAddress(), nil
188	}
189	
190	func (m *multiStrategyRouter) setTargetPortIfNeeded(ctx *types.RoutingContext, readyPodList types.PodList, targetPod *v1.Pod) {
191		if !isMultiPortPods(readyPodList.All()) {
192			return
193		}
194		scorer, ok := m.scorers[string(RouterLeastRequest)]
195		if !ok {
196			return
197		}
198		leastRequest, ok := scorer.(*leastRequestRouter)
199		if !ok {
200			return
201		}
202		if port := selectTargetPortForPodWithLeastRequestCount(leastRequest.cache, targetPod, readyPodList.ListPortsForPod()); port != 0 {
203			ctx.SetTargetPort(port)
204		}
205	}
206	
207	func (m *multiStrategyRouter) runPostRouteUpdates(ctx *types.RoutingContext, readyPodList types.PodList, targetPod *v1.Pod) {
208		for _, item := range m.config.Items {
209			scorer := m.scorers[item.Name]
210			updater, ok := scorer.(types.PostRouteUpdater)
211			if !ok {
212				continue
213			}
214			if err := updater.PostRouteUpdate(ctx, readyPodList, targetPod); err != nil {
215				klog.Warningf("post-route update for strategy %s failed: %v", item.Name, err)
216			}
217		}
218	}
219	
220	// scoreAndRank calculates final scores for all pods and returns the winner
221	func (m *multiStrategyRouter) scoreAndRank(ctx *types.RoutingContext, readyPodList types.PodList) (*v1.Pod, map[*v1.Pod]float64, error) {
222		pods := readyPodList.All()
223		finalScores := make(map[*v1.Pod]float64)
224		logEnabled := klog.V(4).Enabled()
225	
226		// To collect diagnostic info for klog
227		type podDiag struct {
228			StrategyLog []string
229		}
230		var diags map[*v1.Pod]*podDiag
231		if logEnabled {
232			diags = make(map[*v1.Pod]*podDiag)
233			for _, pod := range pods {
234				diags[pod] = &podDiag{}
235			}
236		}
237	
238		// Calculate total weight to act as denominator
239		totalWeight := 0.0
240		for _, item := range m.config.Items {
241			totalWeight += float64(item.Coefficient)
242		}
243	
244		if totalWeight <= 0 {
245			return nil, nil, errors.New("total weight must be greater than zero")
246		}
247	
248		// Iterate over each sub-strategy
249		for _, item := range m.config.Items {
250			scorer := m.scorers[item.Name]
251	
252			// 1. Collect raw scores
253			scores, scored, err := scorer.ScoreAll(ctx, readyPodList)
254			if err != nil {
255				klog.Warningf("Strategy %s failed to score: %v", item.Name, err)
256				scored = make([]bool, len(pods)) // all false
257				scores = make([]float64, len(pods))
258			}
259	
260			// 2. Normalize to [0, 1] based on polarity
261			normScores := m.normalizeScoresArray(scores, scored, scorer.Polarity())
262	
263			// 3. Aggregate into final sum
264			weightFraction := float64(item.Coefficient) / totalWeight
265			for i, pod := range pods {
266				weightedScore := normScores[i] * weightFraction
267				finalScores[pod] += weightedScore
268	
269				if logEnabled {
270					// Record diagnostic information for this pod and strategy
271					rawScoreStr := "N/A"
272					if scored[i] {
273						rawScoreStr = fmt.Sprintf("%.2f", scores[i])
274					}
275					diagStr := fmt.Sprintf("%s(raw:%s, norm:%.2f, weight:%.3f)", item.Name, rawScoreStr, normScores[i], weightedScore)
276					diags[pod].StrategyLog = append(diags[pod].StrategyLog, diagStr)
277				}
278			}
279		}
280	
281		// 4. Find the pod with the highest score
282		var topPods []*v1.Pod
283		maxScore := -1.0
284	
285		for _, pod := range pods {
286			score := finalScores[pod]
287			// handle floating point precision
288			if math.Abs(score-maxScore) < 1e-9 {
289				topPods = append(topPods, pod)
290			} else if score > maxScore {
291				maxScore = score
292				topPods = []*v1.Pod{pod}
293			}
294		}
295	
296		if len(topPods) == 0 {
297			return nil, nil, errors.New("no valid target pod found after scoring")
298		}
299	
300		// Tie-break: select the first pod in the shuffled ready list
301		winner := topPods[0]
302	
303		// 5. Log the routing decision and all candidate metrics to klog
304		if logEnabled {
305			var logBuilder strings.Builder
306			logBuilder.WriteString(fmt.Sprintf("Multi-strategy routing decision for request [%s]. Selected target pod: [%s]. Candidate pod details:\n", ctx.RequestID, winner.Name))
307			for _, pod := range pods {
308				winnerFlag := " "
309				if pod.Name == winner.Name {
310					winnerFlag = "*"
311				}
312				logBuilder.WriteString(fmt.Sprintf("  [%s] Pod: %-30s | FinalScore: %.4f | Details: %s\n",
313					winnerFlag, pod.Name, finalScores[pod], strings.Join(diags[pod].StrategyLog, ", ")))
314			}
315			klog.V(4).Info(logBuilder.String())
316		}
317	
318		return winner, finalScores, nil
319	}
320	
321	// normalizeScoresArray maps raw values to a [0, 1] scale.
322	func (m *multiStrategyRouter) normalizeScoresArray(scores []float64, scored []bool, polarity types.Polarity) []float64 {
323		normScores := make([]float64, len(scores))
324	
325		minVal := math.MaxFloat64
326		maxVal := -math.MaxFloat64
327		scoredCount := 0
328	
329		// Find min and max for scored pods
330		for i, isScored := range scored {
331			if isScored && isFiniteScore(scores[i]) {
332				if scores[i] < minVal {
333					minVal = scores[i]
334				}
335				if scores[i] > maxVal {
336					maxVal = scores[i]
337				}
338				scoredCount++
339			}
340		}
341	
342		if scoredCount == 0 {
343			return normScores // all 0.0
344		}
345	
346		for i, isScored := range scored {
347			if !isScored || !isFiniteScore(scores[i]) {
348				normScores[i] = 0.0 // worst score for unscored pods
349				continue
350			}
351	
352			if maxVal == minVal {
353				normScores[i] = 1.0 // all scored pods get max score if there's no difference
354				continue
355			}
356	
357			if polarity == types.PolarityLeast {
358				// Reverse score if smaller is better: (max - s) / (max - min)
359				normScores[i] = (maxVal - scores[i]) / (maxVal - minVal)
360			} else {
361				// Higher is better: (s - min) / (max - min)
362				normScores[i] = (scores[i] - minVal) / (maxVal - minVal)
363			}
364		}
365	
366		return normScores
367	}
368	
369	func isFiniteScore(score float64) bool {
370		return !math.IsNaN(score) && !math.IsInf(score, 0)
371	}
372	
373	type RouterManager struct {
374		routerInited      context.Context
375		routerDoneInit    context.CancelFunc
376		routerFactory     map[types.RoutingAlgorithm]types.RouterProviderFunc
377		routerConstructor map[types.RoutingAlgorithm]types.RouterProviderRegistrationFunc
378		multiRouterCache  map[string]*multiStrategyRouter
379		routerMu          sync.RWMutex
380	}
381	
382	func NewRouterManager() *RouterManager {
383		rm := &RouterManager{}
384		rm.routerInited, rm.routerDoneInit = context.WithTimeout(context.Background(), 5*time.Second)
385		rm.routerFactory = make(map[types.RoutingAlgorithm]types.RouterProviderFunc)
386		rm.routerConstructor = make(map[types.RoutingAlgorithm]types.RouterProviderRegistrationFunc)
387		rm.multiRouterCache = make(map[string]*multiStrategyRouter)
388		return rm
389	}
390	
391	// Validate validates if user provided routing routers is supported by gateway
392	func (rm *RouterManager) Validate(algorithms string) (types.RoutingAlgorithm, bool) {
393		// Parse the strategy configuration using multi-router parsing logic
394		cfg, err := ParseMultiRouterConfig(algorithms)
395		if err != nil {
396			return RouterNotSet, false
397		}
398	
399		rm.routerMu.RLock()
400		defer rm.routerMu.RUnlock()
401	
402		// Validate each strategy in the configuration
403		for _, item := range cfg.Items {
404			provider, ok := rm.routerFactory[types.RoutingAlgorithm(item.Name)]
405			if !ok {
406				return RouterNotSet, false
407			}
408			if len(cfg.Items) > 1 {
409				if provider == nil {
410					return RouterNotSet, false
411				}
412				router, err := provider(types.RoutingAlgorithm(algorithms).NewContext(context.Background(), "", "", "validate", ""))
413				if err != nil {
414					return RouterNotSet, false
415				}
416				if _, ok := router.(types.PodScorer); !ok {
417					return RouterNotSet, false
418				}
419			}
420		}
421	
422		// Return the original algorithms string to keep it intact in headers
423		return types.RoutingAlgorithm(algorithms), true
424	}
425	func Validate(algorithms string) (types.RoutingAlgorithm, bool) {
426		return defaultRM.Validate(algorithms)
427	}
428	
429	// Select the user provided router provider supported by gateway, no error reported and fallback to random router
430	// Call Validate before this function to ensure expected behavior.
431	func (rm *RouterManager) Select(ctx *types.RoutingContext) (types.Router, error) {
432		algStr := string(ctx.Algorithm)
433	
434		// Check if it's a multi-strategy config.
435		cfg, err := ParseMultiRouterConfig(algStr)
436		if err == nil {
437			if len(cfg.Items) > 1 {
438				multiRouter, err := rm.getOrCreateMultiStrategyRouter(algStr, cfg, ctx)
439				if err == nil {
440					return multiRouter, nil
441				}
442				// If multi-router initialization fails (e.g. strategy doesn't implement ScoreAll),
443				// we log a debug message and fall back to the traditional single strategy provider below.
444				klog.V(4).Infof("Cannot use multi-strategy router for %s: %v, falling back to legacy single strategy", algStr, err)
445			}
446	
447			// If the parser recognized exactly one valid strategy (e.g. it was an exclusive strategy like "pd"
448			// or just a single strategy that doesn't support ScoreAll), we fallback to that specific strategy.
449			if len(cfg.Items) == 1 {
450				algStr = cfg.Items[0].Name
451			}
452		} else {
453			// Log the error but don't fallback to Random. Allow the request to fail down the line,
454			// preserving the HTTP 400 Bad Request API contract.
455			klog.Warningf("Failed to parse multi-strategy config '%s': %v", algStr, err)
456		}
457	
458		// Legacy Single strategy fallback
459		rm.routerMu.RLock()
460		defer rm.routerMu.RUnlock()
461		if provider, ok := rm.routerFactory[types.RoutingAlgorithm(algStr)]; ok {
462			return provider(ctx)
463		} else {
464			// Return an error rather than falling back to random to preserve 400 Bad Request
465			return nil, fmt.Errorf("unsupported router strategy: %s", algStr)
466		}
467	}
468	func Select(ctx *types.RoutingContext) (types.Router, error) {
469		return defaultRM.Select(ctx)
470	}
471	
472	func (rm *RouterManager) getOrCreateMultiStrategyRouter(algStr string, cfg *MultiRouterConfig, ctx *types.RoutingContext) (*multiStrategyRouter, error) {
473		rm.routerMu.RLock()
474		if router, ok := rm.multiRouterCache[algStr]; ok {
475			rm.routerMu.RUnlock()
476			return router, nil
477		}
478		rm.routerMu.RUnlock()
479	
480		router, err := newMultiStrategyRouter(cfg, rm, ctx)
481		if err != nil {
482			return nil, err
483		}
484	
485		rm.routerMu.Lock()
486		defer rm.routerMu.Unlock()
487		if cached, ok := rm.multiRouterCache[algStr]; ok {
488			return cached, nil
489		}
490		rm.multiRouterCache[algStr] = router
491		return router, nil
492	}
493	
494	func (rm *RouterManager) Register(algorithm types.RoutingAlgorithm, constructor types.RouterConstructor) {
495		rm.routerMu.Lock()
496		defer rm.routerMu.Unlock()
497		rm.multiRouterCache = make(map[string]*multiStrategyRouter)
498		rm.routerConstructor[algorithm] = func() types.RouterProviderFunc {
499			router, err := constructor()
500			if err != nil {
501				klog.Errorf("Failed to construct router for %s: %v", algorithm, err)
502				return nil
503			}
504			return func(_ *types.RoutingContext) (types.Router, error) {
505				return router, nil
506			}
507		}
508	}
509	func Register(algorithm types.RoutingAlgorithm, constructor types.RouterConstructor) {
510		defaultRM.Register(algorithm, constructor)
511	}
512	
513	func (rm *RouterManager) RegisterProvider(algorithm types.RoutingAlgorithm, provider types.RouterProviderFunc) {
514		rm.routerMu.Lock()
515		defer rm.routerMu.Unlock()
516		rm.routerFactory[algorithm] = provider
517		rm.multiRouterCache = make(map[string]*multiStrategyRouter)
518		klog.V(4).Infof("Registered router for %s", algorithm)
519	}
520	func RegisterProvider(algorithm types.RoutingAlgorithm, provider types.RouterProviderFunc) {
521		defaultRM.RegisterProvider(algorithm, provider)
522	}
523	
524	func (rm *RouterManager) SetFallback(router types.Router, fallback types.RoutingAlgorithm) error {
525		r, ok := router.(types.FallbackRouter)
526		if !ok {
527			return ErrFallbackNotSupported
528		}
529	
530		<-rm.routerInited.Done()
531		initErr := rm.routerInited.Err()
532		if initErr != context.Canceled {
533			return fmt.Errorf("router did not initialized: %v", initErr)
534		}
535	
536		rm.routerMu.RLock()
537		defer rm.routerMu.RUnlock()
538	
539		if provider, ok := rm.routerFactory[fallback]; !ok {
540			return ErrFallbackNotRegistered
541		} else {
542			r.SetFallback(fallback, provider)
543		}
544		return nil
545	}
546	func SetFallback(router types.Router, fallback types.RoutingAlgorithm) error {
547		return defaultRM.SetFallback(router, fallback)
548	}
549	
550	func (rm *RouterManager) Init() {
551		rm.routerMu.Lock()
552		defer rm.routerMu.Unlock()
553		for algorithm, constructor := range rm.routerConstructor {
554			rm.routerFactory[algorithm] = constructor()
555			klog.V(4).Infof("Registered router for %s", algorithm)
556		}
557		rm.multiRouterCache = make(map[string]*multiStrategyRouter)
558		rm.routerDoneInit()
559	}
560	func Init() {
561		defaultRM.Init()
562	}
