280			if !exists || len(podPorts) == 0 {
281				continue
282			}
283	
284			for _, port := range podPorts {
285				var metricName string
286				var keyName string
287	
288				if len(podPorts) == 1 {
289					metricName = metrics.RealtimeNumRequestsRunning
290					keyName = pod.Name
291				} else {
292					metricName = metrics.RealtimeNumRequestsRunning + "/" + strconv.Itoa(port)
293					keyName = pod.Name + "/" + strconv.Itoa(port)
294				}
295	
296				var count int
297				if val, err := cache.GetMetricValueByPod(pod.Name, pod.Namespace, metricName); err == nil && val != nil {
298					count = int(val.GetSimpleValue())
299				}
300				podRequestCount[keyName] = count
301			}
302		}
303	
304		return podRequestCount
305	}
